def solve(payload):
    a, b = payload['a'], payload['b']
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a) and i < len(b) and a[i] == b[i]:
            result.append({'op': 'equal', 'value': a[i]})
        else:
            if i < len(a):
                result.append({'op': 'delete', 'value': a[i]})
            if i < len(b):
                result.append({'op': 'insert', 'value': b[i]})
    return result

