def solve(payload):
    a, b = payload['a'], payload['b']
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n, -1, -1):
        for j in range(m, -1, -1):
            if i == n:
                dp[i][j] = m - j
            elif j == m:
                dp[i][j] = n - i
            elif a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1]
            else:
                dp[i][j] = 1 + min(dp[i + 1][j], dp[i][j + 1])
    result, i, j = [], 0, 0
    while i < n or j < m:
        if i < n and j < m and a[i] == b[j]:
            result.append({'op': 'equal', 'value': a[i]})
            i, j = i + 1, j + 1
        elif i < n and (j == m or dp[i + 1][j] <= dp[i][j + 1]):
            result.append({'op': 'delete', 'value': a[i]})
            i += 1
        else:
            result.append({'op': 'insert', 'value': b[j]})
            j += 1
    return result

